const lv_image_dsc_t *icon_image(const char *key)
{
    for (size_t i = 0; i < sizeof(icon_tbl) / sizeof(icon_tbl[0]); i++)
        if (key && strcmp(icon_tbl[i].key, key) == 0) return icon_tbl[i].img;
    return NULL;
}
